import React from 'react';
import { Helmet } from 'react-helmet-async';

function SocialMeta({ funeral, totalCost }) {
  const title = 'แผนงานศพของฉัน';
  const description = `สไตล์: ${funeral.style}\nงบประมาณ: ${totalCost.toLocaleString()} บาท\nจุดคุ้มทุน: ${Math.ceil(totalCost / 500)} คน (500 บาท/คน)`;
  
  // Using a simple gradient as the social sharing image
  const imageUrl = `data:image/svg+xml,${encodeURIComponent(`
    <svg width="1200" height="630" xmlns="http://www.w3.org/2000/svg">
      <defs>
        <linearGradient id="grad" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" style="stop-color:#1F2937;stop-opacity:1" />
          <stop offset="100%" style="stop-color:#111827;stop-opacity:1" />
        </linearGradient>
      </defs>
      <rect width="100%" height="100%" fill="url(#grad)"/>
      <text x="50%" y="50%" font-family="Arial" font-size="48" fill="white" text-anchor="middle">
        ${title}
      </text>
    </svg>
  `)}`;

  return (
    <Helmet>
      {/* Primary Meta Tags */}
      <title>{title}</title>
      <meta name="title" content={title} />
      <meta name="description" content={description} />

      {/* Open Graph / Facebook */}
      <meta property="og:type" content="website" />
      <meta property="og:url" content={window.location.href} />
      <meta property="og:title" content={title} />
      <meta property="og:description" content={description} />
      <meta property="og:image" content={imageUrl} />

      {/* Twitter */}
      <meta property="twitter:card" content="summary_large_image" />
      <meta property="twitter:url" content={window.location.href} />
      <meta property="twitter:title" content={title} />
      <meta property="twitter:description" content={description} />
      <meta property="twitter:image" content={imageUrl} />

      {/* Additional Meta Tags */}
      <meta name="theme-color" content="#1F2937" />
      <meta name="keywords" content="วางแผนงานศพ, เตรียมตัวก่อนตาย, งานศพ, การจัดการงานศพ" />
    </Helmet>
  );
}

export default SocialMeta;
